136	
137	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
138	     *  separated by '@', none of which contain whitespace or a second '@'. */
139	    private static final java.util.regex.Pattern EMAIL_PATTERN =
140	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
141	
142	    /** Disposable email domains that are not accepted as an owner's email. */
143	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
144	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
145	
146	    /**
147	     * Normalize the optional email: absent stays absent; when present it must be syntactically
148	     * valid and is lower-cased. Returns {@code false} if present but invalid, including when its
149	     * domain is on the disposable-domain blocklist.
150	     */
151	    private boolean normalizeEmail(Owner owner) {
152	        String email = owner.getEmail();
153	        if (email == null || email.isEmpty()) {
154	            owner.setEmail(null);
155	            return true;
156	        }
157	        if (!EMAIL_PATTERN.matcher(email).matches()) {
158	            return false;
159	        }
160	        email = email.toLowerCase(java.util.Locale.ROOT);
161	        String domain = email.substring(email.indexOf('@') + 1);
162	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
163	            return false;
164	        }
165	        owner.setEmail(email);
166	        return true;
167	    }
168	
169	    /**
170	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
171	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
172	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
173	     *
174	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
175	     *         a valid E.164 number.
176	     */
177	    private static String toE164(String raw) {
178	        if (raw == null) {
179	            return null;
180	        }
181	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
182	        String digits;
183	        if (cleaned.startsWith("+")) {
184	            digits = cleaned.substring(1);
185	        } else {
186	            if (cleaned.startsWith("0")) {
187	                cleaned = cleaned.substring(1);
188	            }
189	            digits = "61" + cleaned;
190	        }
191	        if (!digits.matches("\\d{8,15}")) {
192	            return null;
193	        }
194	        return "+" + digits;
195	    }
196	
197	    /**
198	     * Validate the national-number length of a canonical E.164 string against its country code:
199	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
200	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
201	     * string produced by {@link #toE164}.
202	     *
203	     * @return {@code true} when the national-number length is correct for the country code.
204	     */
205	    private static boolean hasValidNationalLength(String e164) {
206	        String digits = e164.substring(1);
207	        if (digits.startsWith("61")) {
208	            return digits.length() - 2 == 9;
209	        }
210	        if (digits.startsWith("1")) {
211	            return digits.length() - 1 == 10;
212	        }
213	        return true;
214	    }
215	
216	    /**
217	     * Build the unified member id {@code <REGION><FY><HASH8><CHK>}: REGION is the region code derived
218	     * from the owner's postcode (NSW/VIC/QLD, or {@code UNKNOWN} when the postcode is absent or in no
219	     * known range); FY is the two-digit fiscal year of the owner's (business-day-adjusted)
220	     * registrationDate; HASH8 is the first 8 upper-case hex characters of SHA-256 over the
221	     * concatenation of the owner's normalized (E.164) telephone and last name; and CHK is a single
222	     * Luhn check digit over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW273F9A0C177}).
223	     * No sequence numbers are used, so the base id is a pure function of the owner's region, fiscal
224	     * year and region-and-hash identity. When that base id collides with an existing owner's memberId,
225	     * {@code -<n>} is appended with the smallest {@code n} of 2 or more that makes it unique, returning
226	     * the de-duplicated id.
227	     */
228	    private String memberIdFor(Owner owner) {
229	        String region = ownerMapper.regionFromPostcode(owner);
230	        if (region == null) {
231	            region = "UNKNOWN";
232	        }
233	        String fy = String.format("%02d", ownerMapper.fiscalYearOf(owner.getRegistrationDate()) % 100);
234	        String core = region + fy + hash8(owner.getTelephone(), owner.getLastName());
235	        String base = core + luhn(core);
236	
237	        java.util.Set<String> existingIds = new java.util.HashSet<>();
238	        for (Owner existing : this.clinicService.findAllOwners()) {
239	            String id = existing.getMemberId();
240	            if (id != null) {
241	                existingIds.add(id);
242	            }
243	        }
244	        if (!existingIds.contains(base)) {
245	            return base;
246	        }
247	        for (int n = 2; ; n++) {
248	            String candidate = base + "-" + n;
249	            if (!existingIds.contains(candidate)) {
250	                return candidate;
251	            }
252	        }
253	    }
254	
255	    /**
256	     * A single Luhn check digit (0-9) over the digits contained in {@code value}; non-digit characters
257	     * are ignored.
258	     */
259	    private static int luhn(String value) {
260	        int sum = 0;
261	        boolean dbl = true;
262	        for (int i = value.length() - 1; i >= 0; i--) {
263	            char c = value.charAt(i);
264	            if (c < '0' || c > '9') {
265	                continue;
266	            }
267	            int d = c - '0';
268	            if (dbl) {
269	                d *= 2;
270	                if (d > 9) {
271	                    d -= 9;
272	                }
273	            }
274	            sum += d;
275	            dbl = !dbl;
276	        }
277	        return (10 - (sum % 10)) % 10;
278	    }
279	
280	    /**
281	     * First 8 upper-case hex characters (the first 4 bytes) of SHA-256 over
282	     * {@code normalizedTelephone + lastName}, treating a {@code null} component as empty.
283	     */
284	    private static String hash8(String normalizedTelephone, String lastName) {
285	        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
286	            + (lastName == null ? "" : lastName);
287	        try {
288	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
289	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
290	            StringBuilder sb = new StringBuilder(8);
291	            for (int i = 0; i < 4; i++) {
292	                sb.append(String.format("%02X", digest[i]));
293	            }
294	            return sb.toString();
295	        }
296	        catch (java.security.NoSuchAlgorithmException e) {
297	            throw new IllegalStateException(e);
298	        }
299	    }
300	
301	    /** Common street-type abbreviations expanded during address normalization. */
302	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
303	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
304	
305	    /**
306	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
307	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
308	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
309	     */
310	    private static String normalizeAddress(String value) {
311	        if (value == null) {
312	            return "";
313	        }
314	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
315	        if (collapsed.isEmpty()) {
316	            return "";
317	        }
318	        String[] tokens = collapsed.split(" ");
319	        StringBuilder sb = new StringBuilder(collapsed.length());
320	        for (int i = 0; i < tokens.length; i++) {
321	            if (i > 0) {
322	                sb.append(' ');
323	            }
324	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
325	        }
326	        return sb.toString();
327	    }
328	
329	    /**
330	     * Resolve and normalize the owner's postal address, preferring the structured form.
331	     *
332	     * <p>When a non-blank {@code addressLine1} is supplied the structured form is used: it, and the
333	     * optional {@code addressLine2}, are normalized in place and the composed address is the
334	     * normalized addressLine1 with a single space and the normalized addressLine2 appended when
335	     * addressLine2 is present. Otherwise the flat {@code address} input is normalized. Returns
336	     * {@code null} when neither form yields a non-empty address, so the caller can reject the
337	     * request.
338	     */
339	    private String composeAddress(Owner owner) {
340	        String line1 = owner.getAddressLine1();
341	        if (line1 != null && !line1.isBlank()) {
342	            String normalizedLine1 = normalizeAddress(line1);
343	            owner.setAddressLine1(normalizedLine1);
344	            String line2 = owner.getAddressLine2();
345	            if (line2 != null && !line2.isBlank()) {
346	                String normalizedLine2 = normalizeAddress(line2);
347	                owner.setAddressLine2(normalizedLine2);
348	                return normalizedLine1 + " " + normalizedLine2;
349	            }
350	            owner.setAddressLine2(null);
351	            return normalizedLine1.isEmpty() ? null : normalizedLine1;
352	        }
353	        String normalized = normalizeAddress(owner.getAddress());
354	        return normalized.isEmpty() ? null : normalized;
355	    }
356	
357	    /**
358	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
359	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
360	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
361	     */
362	    private static String normalizeForHousehold(String value) {
363	        if (value == null) {
364	            return "";
365	        }
366	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
367	    }
368	
369	    /**
370	     * Return the owners that already share this owner's household, i.e. resolve to the same
371	     * deterministic {@link #householdIdFor(Owner) householdId} (same normalized last name and
372	     * postcode).
373	     */
374	    private List<Owner> householdMembers(Owner owner) {
375	        String householdId = householdIdFor(owner);
376	        List<Owner> members = new java.util.ArrayList<>();
377	        for (Owner existing : this.clinicService.findAllOwners()) {
378	            if (existing.isDeleted()) {
379	                continue;
380	            }
381	            if (householdId.equals(householdIdFor(existing))) {
382	                members.add(existing);
383	            }
384	        }
385	        return members;
386	    }
387	
388	    /**
389	     * Return {@code true} when another owner already shares this owner's household, i.e. resolves to
390	     * the same deterministic {@link #householdIdFor(Owner) householdId}.
391	     */
392	    private boolean sharesHouseholdWithExisting(Owner owner) {
393	        return !householdMembers(owner).isEmpty();
394	    }
395	
396	    /**
397	     * Count the existing owners that share this owner's first name and last name, compared
398	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
399	     */
400	    private int namesakeCount(Owner owner) {
401	        String firstName = owner.getFirstName();
402	        String lastName = owner.getLastName();
403	        int count = 0;
404	        for (Owner existing : this.clinicService.findAllOwners()) {
405	            if (firstName != null && lastName != null
406	                && firstName.equalsIgnoreCase(existing.getFirstName())
407	                && lastName.equalsIgnoreCase(existing.getLastName())) {
408	                count++;
409	            }
410	        }
411	        return count;
412	    }
413	
414	    /**
415	     * A stable, shared household identifier: the first 12 hex characters of SHA-256 over
416	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes an empty string).
417	     * Because it is a pure function of the last name and postcode, every owner in the same household
418	     * deterministically resolves to the same value.
419	     */
420	    private static String householdIdFor(Owner owner) {
421	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
422	        String key = normalizeForHousehold(owner.getLastName()) + "|" + postcode;
423	        try {
424	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
425	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
426	            StringBuilder sb = new StringBuilder(12);
427	            for (int i = 0; i < 6; i++) {
428	                sb.append(String.format("%02X", digest[i]));
429	            }
430	            return sb.toString();
431	        }
432	        catch (java.security.NoSuchAlgorithmException e) {
433	            throw new IllegalStateException(e);
434	        }
435	    }
436	
437	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
438	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
439	        "NSW", new int[] {2000, 2099},
440	        "VIC", new int[] {3000, 3099},
441	        "QLD", new int[] {4000, 4099});
442	
443	    /**
444	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
445	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
446	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
447	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
448	     * postcode.
449	     */
450	    private boolean isPostcodeValid(Owner owner) {
451	        String postcode = owner.getPostcode();
452	        if (postcode == null || postcode.isEmpty()) {
453	            return true;
454	        }
455	        if (!postcode.matches("\\d{4}")) {
456	            return false;
457	        }
458	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
459	        if (range == null) {
460	            return true;
461	        }
462	        int value = Integer.parseInt(postcode);
463	        return value >= range[0] && value <= range[1];
464	    }
465	
466	    /**
467	     * Find an existing owner that makes this (already known to be non-hard-duplicate) owner a
468	     * "possible duplicate": one whose last name shares this owner's {@link Owner#soundex(String)
469	     * soundex} and whose postcode matches, yet whose whole {@link Owner#getIdentityKey() identityKey}
470	     * differs (so it is not a hard duplicate). When several match, the one with the smallest id is
471	     * chosen so the result is deterministic. Returns {@code null} when the owner has no postcode or no
472	     * such existing owner exists.
473	     */
474	    private Owner possibleDuplicateOf(Owner owner) {
475	        String lastName = owner.getLastName();
476	        String postcode = owner.getPostcode();
477	        if (lastName == null || postcode == null || postcode.isEmpty()) {
478	            return null;
479	        }
480	        String soundex = Owner.soundex(lastName);
481	        String identityKey = owner.getIdentityKey();
482	        Owner match = null;
483	        for (Owner existing : this.clinicService.findAllOwners()) {
484	            if (soundex.equals(Owner.soundex(existing.getLastName()))
485	                && postcode.equals(existing.getPostcode())
486	                && !identityKey.equals(existing.getIdentityKey())) {
487	                if (match == null || (existing.getId() != null && match.getId() != null
488	                    && existing.getId() < match.getId())) {
489	                    match = existing;
490	                }
491	            }
492	        }
493	        return match;
494	    }
495	
496	    /** Maximum number of owners permitted in a single city. */
497	    private static final int CITY_CAPACITY = 50;
498	
499	    /**
500	     * Number of owners already in a city at or beyond which a capacity warning is flagged (the city
501	     * is approaching the {@link #CITY_CAPACITY} hard limit). A city holding 40-49 owners warns.
502	     */
503	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
504	
505	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
506	    private static final int DAILY_CREATE_LIMIT = 100;
507	
508	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
509	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
510	
511	    /**
512	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
513	     * Used to enforce the per-city capacity on create (before this owner is saved).
514	     */
515	    private int cityOwnerCount(Owner owner) {
516	        String city = owner.getCity();
517	        int count = 0;
518	        for (Owner existing : this.clinicService.findAllOwners()) {
519	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
520	                count++;
521	            }
522	        }
523	        return count;
524	    }
525	
526	    /** Fixed public holidays the business-day roll skips. */
527	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
528	        java.time.LocalDate.parse("2026-01-01"),
529	        java.time.LocalDate.parse("2026-01-26"),
530	        java.time.LocalDate.parse("2026-04-25"),
531	        java.time.LocalDate.parse("2026-12-25"),
532	        java.time.LocalDate.parse("2026-12-28"));
533	
534	    /**
535	     * Roll a registration date forward onto a business day: any Saturday, Sunday or listed public
536	     * holiday is advanced one day at a time until a non-holiday weekday is reached; a date that is
537	     * already a non-holiday weekday is returned unchanged. Applied to the effective registration date
538	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
539	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
540	     */
541	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
542	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
543	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
544	            || PUBLIC_HOLIDAYS.contains(date)) {
545	            date = date.plusDays(1);
546	        }
547	        return date;
548	    }
549	
550	    /**
551	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
552	     * per-day create limit on create (before this owner is saved).
553	     */
554	    private int ownersRegisteredOn(java.time.LocalDate day) {
555	        int count = 0;
556	        for (Owner existing : this.clinicService.findAllOwners()) {
557	            if (day.equals(existing.getRegistrationDate())) {
558	                count++;
559	            }
560	        }
561	        return count;
562	    }
563	
564	    /**
565	     * The {@code Idempotency-Key} header of the request currently being handled, or {@code null} when
566	     * the header is absent, blank or no servlet request is bound to the calling thread. The generated
567	     * {@link OwnersApi#addOwner} signature carries no header parameter, so it is read from the bound
568	     * request context.
569	     */
570	    private static String currentIdempotencyKey() {
571	        org.springframework.web.context.request.RequestAttributes attrs =
572	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
573	        if (attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs) {
574	            String key = servletAttrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
575	            if (key != null && !key.isBlank()) {
576	                return key;
577	            }
578	        }
579	        return null;
580	    }
581	
582	    /**
583	     * The owner's primary identifier, carried by the structured owner-created audit event: the
584	     * unified {@code memberId}.
585	     */
586	    private String primaryIdentifier(Owner owner) {
587	        return owner.getMemberId();
588	    }
589	
590	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
591	    @Override
592	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
593	        HttpHeaders headers = new HttpHeaders();
594	        // Idempotent create: when this request carries an Idempotency-Key we have already seen, return
595	        // the owner originally created for that key (200) instead of creating a duplicate.
596	        String idempotencyKey = currentIdempotencyKey();
597	        if (idempotencyKey != null) {
598	            Integer existingId = idempotentCreates.get(idempotencyKey);
599	            if (existingId != null) {
600	                Owner existing = this.clinicService.findOwnerById(existingId);
601	                if (existing != null) {
602	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
603	                }
604	            }
605	        }
606	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
607	        if (!isPostcodeValid(owner)) {
608	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
609	        }
610	        String telephone = toE164(owner.getTelephone());
611	        if (telephone == null || !hasValidNationalLength(telephone)) {
612	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
613	        }
614	        if (!normalizeEmail(owner)) {
615	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
616	        }
617	        String address = composeAddress(owner);
618	        if (address == null) {
619	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
620	        }
621	        owner.setAddress(address);
622	        owner.setTelephone(telephone);
623	        if (owner.getRegistrationDate() != null
624	            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
625	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
626	        }
627	        java.time.LocalDate registrationDate = toBusinessDay(
628	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
629	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
630	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
631	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
632	        }
633	        int cityOwnerCount = cityOwnerCount(owner);
634	        if (cityOwnerCount >= CITY_CAPACITY) {
635	            return new ResponseEntity<>(HttpStatus.CONFLICT);
636	        }
637	        // The householdId is deterministic (SHA-256 over normalized lastName + '|' + postcode), so
638	        // owners with the same last name and postcode automatically share it. The link is no longer
639	        // created by copying an existing owner's id around.
640	        owner.setHouseholdId(householdIdFor(owner));
641	        List<Owner> householdMembers = householdMembers(owner);
642	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
643	        boolean declaredHouseholdMember = sharesHousehold && !householdMembers.isEmpty();
644	
645	        // Hard duplicate: a new owner whose identityKey (SHA-256 over telephone|email|soundex(lastName))
646	        // equals an existing, non-deleted owner's is the same identity and is always rejected. This is
647	        // now the single duplicate check: because the telephone is part of the key, two owners with the
648	        // same last name and postcode but different telephones no longer collide here and instead fall
649	        // through to the possible-duplicate (soft-match) flagging below.
650	        String identityKey = owner.getIdentityKey();
651	        for (Owner existing : this.clinicService.findAllOwners()) {
652	            if (existing.isDeleted()) {
653	                continue;
654	            }
655	            if (identityKey.equals(existing.getIdentityKey())) {
656	                return new ResponseEntity<>(HttpStatus.CONFLICT);
657	            }
658	        }
659	        // Household member: another owner already shares this (last name, postcode) household. This
660	        // is no longer rejected as a duplicate — an exact byte-for-byte identity match is already
661	        // caught above, and a distinct additional household member is admitted with its membership
662	        // level capped (see below) at one above the current household maximum. The 'sharesHousehold'
663	        // flag now only signals that the caller vouches for the member, suppressing the
664	        // possible-duplicate flagging below.
665	        // A declared household member is not a suspected duplicate. Otherwise, flag an owner whose
666	        // last name shares an existing owner's soundex and postcode but whose identityKey differs.
667	        if (declaredHouseholdMember) {
668	            owner.setPossibleDuplicate(false);
669	            owner.setPossibleDuplicateOf(null);
670	        }
671	        else {
672	            Owner duplicateOf = possibleDuplicateOf(owner);
673	            owner.setPossibleDuplicate(duplicateOf != null);
674	            owner.setPossibleDuplicateOf(duplicateOf == null ? null : duplicateOf.getId());
675	        }
676	        owner.setNamesakeCount(namesakeCount(owner));
677	        owner.setHouseholdSize(householdMembers.size() + 1);
678	        // Level ceiling: a new owner's membershipLevel cannot exceed one above the current maximum
679	        // membershipLevel among their existing household members. With no existing member, no cap.
680	        if (householdMembers.isEmpty()) {
681	            owner.setMembershipLevelCap(null);
682	        }
683	        else {
684	            int maxHouseholdLevel = householdMembers.stream()
685	                .mapToInt(member -> ownerMapper.membershipLevel(member))
686	                .max()
687	                .getAsInt();
688	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
689	        }
690	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
691	        owner.setCapacityWarning(cityOwnerCount >= CITY_CAPACITY_WARNING_THRESHOLD);
692	        owner.setRegistrationDate(registrationDate);
693	        owner.setMemberId(memberIdFor(owner));
694	        this.clinicService.saveOwner(owner);
695	        if (idempotencyKey != null) {
696	            idempotentCreates.put(idempotencyKey, owner.getId());
697	        }
698	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
699	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
700	            ownerMapper.membershipLevel(owner));
701	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQ.incrementAndGet(), owner.getId(),
702	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner), "OWNER_CREATED");
703	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
704	        // Enqueue a welcome notification carrying the owner id and the memberId.
705	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
706	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
707	        headers.setLocation(UriComponentsBuilder.newInstance()
708	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
709	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
710	    }
711	
712	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
713	    @Override
714	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
715	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
716	        if (currentOwner == null) {
717	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
718	        }
719	        currentOwner.setAddress(ownerFieldsDto.getAddress());
720	        currentOwner.setCity(ownerFieldsDto.getCity());
721	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
722	        currentOwner.setLastName(ownerFieldsDto.getLastName());
723	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
724	        currentOwner.setEmail(ownerFieldsDto.getEmail());
725	        if (!normalizeEmail(currentOwner)) {
726	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
727	        }
728	        this.clinicService.saveOwner(currentOwner);
729	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
730	    }
731	
732	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
733	    @Transactional
734	    @Override
735	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
736	        Owner owner = this.clinicService.findOwnerById(ownerId);
737	        if (owner == null) {
738	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
739	        }
740	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
741	        owner.setDeleted(true);
742	        this.clinicService.saveOwner(owner);
743	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
744	    }
745	
746	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
747	    @Override
748	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
749	        Owner owner = this.clinicService.findOwnerById(ownerId);
750	        if (owner == null) {
751	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
752	        }
753	        HttpHeaders headers = new HttpHeaders();
754	        Pet pet = petMapper.toPet(petFieldsDto);
755	        owner.setId(ownerId);
756	        pet.setOwner(owner);
757	        pet.getType().setName(null);
758	        this.clinicService.savePet(pet);
759	        PetDto petDto = petMapper.toPetDto(pet);
760	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
761	            .buildAndExpand(pet.getId()).toUri());
762	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
763	    }
764	
765	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
766	    @Override
767	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
768	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
769	        if (currentOwner != null) {
770	            Pet currentPet = this.clinicService.findPetById(petId);
771	            if (currentPet != null) {
772	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
773	                currentPet.setName(petFieldsDto.getName());
774	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
775	                this.clinicService.savePet(currentPet);
776	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
777	            }
778	        }
779	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
780	    }
781	
782	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
783	    @Override
784	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
785	        HttpHeaders headers = new HttpHeaders();
786	        Visit visit = visitMapper.toVisit(visitFieldsDto);
787	        Pet pet = new Pet();
788	        pet.setId(petId);
789	        visit.setPet(pet);
790	        this.clinicService.saveVisit(visit);
791	        VisitDto visitDto = visitMapper.toVisitDto(visit);
792	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
793	            .buildAndExpand(visit.getId()).toUri());
794	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
795	    }
796	
797	
798	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
799	    @Override
800	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
801	        Owner owner = this.clinicService.findOwnerById(ownerId);
802	        if (owner != null) {
803	            Pet pet = owner.getPet(petId);
804	            if (pet != null) {
805	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
806	            }
807	        }
808	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
809	    }
810	}
