149	     * mapping method and apply it to every string property.
150	     */
151	    private String memberRegion(String memberId) {
152	        if (memberId == null) {
153	            return null;
154	        }
155	        int i = 0;
156	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
157	            i++;
158	        }
159	        return i == 0 ? null : memberId.substring(0, i);
160	    }
161	
162	    /**
