202	        String city = owner.getCity();
203	        if (city == null) {
204	            return "UNKNOWN";
205	        }
206	        switch (city) {
207	            case "Sydney":
208	                return "NSW";
209	            case "Melbourne":
210	                return "VIC";
211	            case "Brisbane":
212	                return "QLD";
