252	        int points = 0;
253	        String email = owner.getEmail();
254	        if (email != null && !email.isEmpty()) {
255	            points += 2;
256	        }
257	        Integer namesakeCount = owner.getNamesakeCount();
258	        if (namesakeCount != null && namesakeCount == 0) {
259	            points += 1;
260	        }
261	        Integer householdSize = owner.getHouseholdSize();
262	        if (householdSize != null && householdSize >= 3) {
263	            points += 2;
264	        }
265	        if (tenureFiscalYears(owner) > 1) {
266	            points += 3;
267	        }
268	        return points;
269	    }
270	
271	    /**
272	     * Returns the owner's numeric membership level, derived from {@link #membershipPoints(Owner)}:
273	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or
274	     * more points. The derived level is then capped by {@link Owner#getMembershipLevelCap()} when
275	     * present, so a new owner's level cannot exceed one above the highest level in their household.
276	     */
277	    default Integer membershipLevel(Owner owner) {
278	        int points = membershipPoints(owner);
279	        int level;
280	        if (points <= 1) {
281	            level = 1;
282	        }
283	        else if (points <= 3) {
284	            level = 2;
285	        }
286	        else if (points <= 5) {
287	            level = 3;
288	        }
289	        else {
290	            level = 4;
291	        }
292	        Integer cap = owner.getMembershipLevelCap();
293	        if (cap != null && level > cap) {
294	            level = cap;
295	        }
296	        return level;
297	    }
298	
299	    /**
300	     * The owner's tenure in whole elapsed fiscal years: the number of fiscal-year boundaries
301	     * (1 July) crossed between {@code registrationDate} and the current date. A newly created
302	     * owner (registered in the current fiscal year) has zero tenure, and a missing
303	     * registrationDate (e.g. legacy records) is likewise treated as zero.
304	     */
305	    default long tenureFiscalYears(Owner owner) {
306	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
307	        if (registrationDate == null) {
308	            return 0;
309	        }
310	        long years = fiscalYearOf(java.time.LocalDate.now()) - fiscalYearOf(registrationDate);
311	        return Math.max(years, 0);
312	    }
313	
314	    /**
315	     * The fiscal year (a four-digit calendar year) that the given date falls in. The fiscal year
316	     * starts on 1 July and is identified by the calendar year in which it ends, so a date on or
317	     * after 1 July belongs to the fiscal year of the following calendar year.
318	     */
319	    default int fiscalYearOf(java.time.LocalDate date) {
320	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
321	    }
322	
323	    /**
324	     * The owner's fiscal year, formatted 'FY&lt;YY&gt;' where YY is the two-digit {@code <FY>}
325	     * segment of the memberId ({@code <REGION><FY><HASH8><CHK>}), i.e. the fiscal year of the
326	     * business-day-adjusted registrationDate captured at create time (the fiscal year starts on
327	     * 1 July). Returns {@code null} when the memberId is absent or carries no fiscal-year segment.
328	     */
329	    default String fiscalYear(Owner owner) {
330	        String memberId = owner.getMemberId();
331	        String region = memberRegion(memberId);
332	        if (region == null || memberId.length() < region.length() + 2) {
333	            return null;
334	        }
335	        String fy = memberId.substring(region.length(), region.length() + 2);
336	        if (!fy.matches("\\d{2}")) {
337	            return null;
338	        }
339	        return "FY" + fy;
340	    }
341	
342	    /**
343	     * The canonical link to this owner resource: {@code /api/owners/} followed by the
344	     * owner's id. Returns {@code null} when the owner has no id yet.
345	     */
346	    default String selfLink(Owner owner) {
347	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
348	    }
349	
350	    Owner toOwner(OwnerDto ownerDto);
351	
352	    @Mapping(target = "id", ignore = true)
353	    @Mapping(target = "pets", ignore = true)
354	    Owner toOwner(OwnerFieldsDto ownerDto);
355	
356	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
357	
358	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
359	
360	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
361	        OwnerPageDto ownerPageDto = new OwnerPageDto();
362	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
363	        ownerPageDto.setPage(ownerPage.getNumber());
364	        ownerPageDto.setSize(ownerPage.getSize());
365	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
366	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
367	        return ownerPageDto;
368	    }
369	}
